	private static long expected(long[][] pairs, int from, long neighbor, long context) {
		context = Math.max(0, context);
		for (int offset = from; offset < pairs.length; offset++) {
			int comparison = Long.compareUnsigned(pairs[offset][0], neighbor);
			if (comparison > 0 || comparison == 0 && Long.compareUnsigned(pairs[offset][1], context) >= 0) {
				return offset;
			}
		}
		return pairs.length;
	}

